    {
      "text": "Do not allow children to play in or near flood waters, and do not eat food that touched flood waters.",
      "advice_ids": ["fl.children", "fl.food"]
    }
  ],
  "if_you_are": [
    {
      "situation": "vehicle",
      "text": "Do not drive into flooded areas. Abandon your vehicle and move to higher ground if water rises around it.",
      "advice_ids": ["fl.drive"]
